shell.pseudocode:
def shell():
    while True:
        args = input('$ ').split()  # 프롬프트·파싱
        if not args:
            continue
        if args[0] == 'cd':  # 내장 명령: 셸이 직접 처리
            chdir(args[1])
            continue
        pid = fork()  # 자식 프로세스 복제
        if pid == 0:
            exec(args[0], args)  # 자식: 프로그램으로 교체
            exit(127)  # exec 실패 시
        else:
            waitpid(pid)  # 부모: 종료 대기 후 다음 명령

shor-algorithm.pseudocode:
def shor(N):  # N: 홀수 합성수(소수 거듭제곱 아님)
    while True:
        a = random_int(2, N - 1)
        g = gcd(a, N)
        if g > 1:
            return g, N // g  # 우연히 인수 발견
        r = quantum_period(a, N)  # QFT: a^x mod N 주기
        if r % 2 == 1:
            continue  # 홀수 주기 → 다른 a로 재시도
        y = pow(a, r // 2, N)
        if y == N - 1:
            continue  # a^(r/2) ≡ -1 → 재시도
        p = gcd(y - 1, N)  # (y-1)(y+1) ≡ 0 mod N
        return p, N // p

shortest-path.pseudocode:
def dijkstra(graph, src):  # 음수 가중치 없음 전제
    dist = {v: INF for v in graph}
    prev = {v: None for v in graph}
    dist[src] = 0
    pq = MinHeap([(0, src)])  # (거리, 정점)
    while pq:
        d, u = pq.pop_min()
        if d > dist[u]:
            continue  # 이미 더 짧게 확정된 정점
        for v, w in graph[u]:  # 간선 완화
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w
                prev[v] = u  # 최단경로 트리 기록
                pq.push((dist[v], v))
    return dist, prev

shortest-remaining-time-first.pseudocode:
def srtf(procs):  # procs: {이름: (도착, 버스트)}
    remain = {p: b for p, (a, b) in procs.items()}
    time, finish = 0, {}
    while remain:
        ready = [p for p in remain if procs[p][0] <= time]
        if not ready:
            time += 1
            continue
        # 매 시점 잔여시간 최소 선택 → 도착 시 선점 반영
        p = min(ready, key=lambda q: remain[q])
        remain[p] -= 1  # 1단위 실행
        time += 1
        if remain[p] == 0:
            del remain[p]
            finish[p] = time
    waits = [finish[p] - a - b  # 대기 = 종료 − 도착 − 버스트
             for p, (a, b) in procs.items()]
    return finish, sum(waits) / len(waits)
